//DONOTHING JOB (ACCT),'DO NOTHING',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//SYSPRINT DD SYSOUT=*

//DELDATA  JOB (ACCT),'DELETE DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//DELDD    DD DSN=MY.TEMP.DATA,DISP=(MOD,DELETE,DELETE)

//COPYDATA JOB (ACCT),'COPY DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=INPUT.DATA,DISP=SHR
//SYSUT2   DD DSN=OUTPUT.DATA,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD DUMMY

//ALLOCSEQ JOB (ACCT),'ALLOC SEQ',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//NEWFILE  DD DSN=MY.NEW.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=800)

//ALLOCPDS JOB (ACCT),'ALLOC PDS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//NEWPDS   DD DSN=MY.NEW.PDS,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5,5),RLSE),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=800,DSORG=PO)

//LISTCAT  JOB (ACCT),'LIST CATALOG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  LISTCAT ENTRIES(SYS1.*) ALL
/*

//DEFKSDS  JOB (ACCT),'DEFINE KSDS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE CLUSTER (NAME(MY.VSAM.KSDS) -
         INDEXED -
         KEYS(8 0) -
         RECORDSIZE(80 80) -
         TRACKS(10 5) -
         VOLUMES(WORK01)) -
         DATA (NAME(MY.VSAM.KSDS.DATA)) -
         INDEX (NAME(MY.VSAM.KSDS.INDEX))
/*

//DELVSAM  JOB (ACCT),'DELETE VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE MY.VSAM.CLUSTER CLUSTER PURGE
/*

//SORTJOB  JOB (ACCT),'SORT FILE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//COMPRESS JOB (ACCT),'COMPRESS PDS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBCOPY
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=MY.PDS.LIBRARY,DISP=OLD
//SYSUT2   DD DSN=MY.PDS.LIBRARY,DISP=OLD
//SYSIN    DD *
  COPY INDD=SYSUT1,OUTDD=SYSUT2
/*

//COPYMEM  JOB (ACCT),'COPY MEMBERS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBCOPY
//SYSPRINT DD SYSOUT=*
//INPDS    DD DSN=SOURCE.PDS,DISP=SHR
//OUTPDS   DD DSN=TARGET.PDS,DISP=OLD
//SYSIN    DD *
  COPY INDD=INPDS,OUTDD=OUTPDS
  SELECT MEMBER=MYPROG
/*

//PRINTDS  JOB (ACCT),'PRINT DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBPTPCH
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=MY.DATA.FILE,DISP=SHR
//SYSUT2   DD SYSOUT=*
//SYSIN    DD *
  PRINT MAXFLDS=1
  RECORD FIELD=(80)
/*

//CONCAT   JOB (ACCT),'CONCAT FILES',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=FILE1.DATA,DISP=SHR
//         DD DSN=FILE2.DATA,DISP=SHR
//SYSUT2   DD DSN=OUTPUT.COMBINED,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(20,10),RLSE)
//SYSIN    DD DUMMY

//RUNCOBOL JOB (ACCT),'RUN COBOL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=MYPROG
//STEPLIB  DD DSN=MY.LOAD.LIBRARY,DISP=SHR
//SYSOUT   DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//INPUT    DD DSN=MY.INPUT.FILE,DISP=SHR
//OUTPUT   DD DSN=MY.OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)

//COBCOMP  JOB (ACCT),'COMPILE COBOL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IGYCRCTL,PARM='RENT,APOST'
//STEPLIB  DD DSN=IGY.SIGYCOMP,DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSLIN   DD DSN=&&LOADSET,DISP=(MOD,PASS),
//            UNIT=SYSDA,SPACE=(TRK,(3,3))
//SYSUT1   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT2   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT3   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT4   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT5   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT6   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT7   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSIN    DD DSN=MY.COBOL.SOURCE(MYPROG),DISP=SHR

//LINKEDIT JOB (ACCT),'LINK PROGRAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEWL,PARM='LIST,MAP,XREF'
//SYSPRINT DD SYSOUT=*
//SYSLIB   DD DSN=CEE.SCEELKED,DISP=SHR
//SYSLIN   DD DSN=MY.OBJECT.FILE,DISP=SHR
//SYSLMOD  DD DSN=MY.LOAD.LIBRARY(MYPROG),DISP=OLD
//SYSUT1   DD UNIT=SYSDA,SPACE=(CYL,(1,1))

//TSOBATCH JOB (ACCT),'TSO BATCH',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  LISTDS 'SYS1.PARMLIB' MEMBERS
/*

//SUBMIT   JOB (ACCT),'SUBMIT JOB',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=MY.JCL.LIBRARY(MYJOB),DISP=SHR
//SYSUT2   DD SYSOUT=(A,INTRDR)
//SYSIN    DD DUMMY

//CONDJOB  JOB (ACCT),'CONDITIONAL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=PROG1
//SYSOUT   DD SYSOUT=*
//*
//STEP2    EXEC PGM=PROG2,COND=(4,LT)
//SYSOUT   DD SYSOUT=*
//*
//STEP3    EXEC PGM=PROG3,COND=(0,NE,STEP1)
//SYSOUT   DD SYSOUT=*

//USEPROC  JOB (ACCT),'USE PROC',CLASS=A,MSGCLASS=X
//STEP1    EXEC MYPROC
//STEP1.INPUT DD DSN=MY.INPUT.FILE,DISP=SHR
//STEP1.OUTPUT DD DSN=MY.OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)

//INLPROC  JOB (ACCT),'INLINE PROC',CLASS=A,MSGCLASS=X
//*
//MYPROC   PROC
//STEP1    EXEC PGM=IEFBR14
//NEWFILE  DD DSN=&DSN,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//         PEND
//*
//CALL1    EXEC MYPROC,DSN=MY.FILE.ONE
//CALL2    EXEC MYPROC,DSN=MY.FILE.TWO

//REPROVSM JOB (ACCT),'REPRO VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//VSAMFILE DD DSN=MY.VSAM.KSDS,DISP=SHR
//SEQFILE  DD DSN=MY.SEQ.BACKUP,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(50,10),RLSE)
//SYSIN    DD *
  REPRO INFILE(VSAMFILE) OUTFILE(SEQFILE)
/*

//LOADVSAM JOB (ACCT),'LOAD VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//INFILE   DD DSN=MY.SEQ.DATA,DISP=SHR
//VSAMFILE DD DSN=MY.VSAM.KSDS,DISP=OLD
//SYSIN    DD *
  REPRO INFILE(INFILE) OUTFILE(VSAMFILE)
/*

//VERIFY   JOB (ACCT),'VERIFY VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  VERIFY DATASET(MY.VSAM.KSDS)
/*

//DEFGDG   JOB (ACCT),'DEFINE GDG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE GDG (NAME(MY.GDG.BASE) -
         LIMIT(5) -
         NOEMPTY -
         SCRATCH)
/*

//NEWGEN   JOB (ACCT),'NEW GDG GEN',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=MY.INPUT.FILE,DISP=SHR
//SYSUT2   DD DSN=MY.GDG.BASE(+1),DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD DUMMY

//SYMBOLIC JOB (ACCT),'SYMBOLIC',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
// SET DSN=MY.DATASET
// SET VOL=WORK01
//NEWFILE  DD DSN=&DSN,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,VOL=SER=&VOL,
//            SPACE=(TRK,(10,5),RLSE)

//IEHLIST  JOB (ACCT),'IEHLIST',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEHLIST
//SYSPRINT DD SYSOUT=*
//DD1      DD UNIT=SYSDA,VOL=SER=WORK01,DISP=OLD
//SYSIN    DD *
  LISTPDS DSNAME=SYS1.LINKLIB,VOL=SYSDA=SYSRES
/*

//INITTAPE JOB (ACCT),'INIT TAPE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEHINITT
//SYSPRINT DD SYSOUT=*
//TAPE     DD UNIT=TAPE,VOL=(PRIVATE,SER=TAPE01),DISP=OLD
//SYSIN    DD *
  TAPE01 INITT SER=TAPE01,OWNER='HERC01'
/*

//MERGE    JOB (ACCT),'MERGE FILES',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN01 DD DSN=SORTED.FILE1,DISP=SHR
//SORTIN02 DD DSN=SORTED.FILE2,DISP=SHR
//SORTOUT  DD DSN=MERGED.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(20,10),RLSE)
//SYSIN    DD *
  MERGE FIELDS=(1,10,CH,A)
/*

//BACKUP   JOB (ACCT),'DFDSS BACKUP',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=ADRDSSU
//SYSPRINT DD SYSOUT=*
//TAPE     DD DSN=BACKUP.TAPE,UNIT=TAPE,
//            VOL=SER=BKP001,DISP=(NEW,KEEP)
//SYSIN    DD *
  DUMP DATASET(INCLUDE(PROD.**)) -
       OUTDDNAME(TAPE) -
       COMPRESS
/*

//RESTORE  JOB (ACCT),'DFDSS RESTORE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=ADRDSSU
//SYSPRINT DD SYSOUT=*
//TAPE     DD DSN=BACKUP.TAPE,UNIT=TAPE,
//            VOL=SER=BKP001,DISP=OLD
//SYSIN    DD *
  RESTORE DATASET(INCLUDE(**)) -
          INDDNAME(TAPE) -
          REPLACE
/*

//ALTERVSM JOB (ACCT),'ALTER VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  ALTER MY.VSAM.KSDS -
        FREESPACE(20 10) -
        BUFFERSPACE(16384)
/*

//SORTINCL JOB (ACCT),'SORT INCLUDE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
  INCLUDE COND=(15,2,CH,EQ,C'NY')
/*

//SORTOUT  JOB (ACCT),'SORT OUTREC',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD *
  SORT FIELDS=COPY
  OUTREC FIELDS=(1,10,20,15,50,20)
/*

//JCLLIB   JOB (ACCT),'JCLLIB',CLASS=A,MSGCLASS=X
//MYLIB    JCLLIB ORDER=(MY.PROC.LIBRARY,SYS1.PROCLIB)
//STEP1    EXEC MYPROC
//STEP1.SYSOUT DD SYSOUT=*

//ICETOOL  JOB (ACCT),'ICETOOL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=ICETOOL
//TOOLMSG  DD SYSOUT=*
//DFSMSG   DD SYSOUT=*
//INFILE   DD DSN=INPUT.FILE,DISP=SHR
//OUTFILE  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//TOOLIN   DD *
  COPY FROM(INFILE) TO(OUTFILE) USING(CTL1)
/*
//CTL1CNTL DD *
  SORT FIELDS=(1,10,CH,A)
/*

//MULTISTEP JOB (ACCT),'MULTI STEP',CLASS=A,MSGCLASS=X
//*
//STEP1    EXEC PGM=IEFBR14
//NEWFILE  DD DSN=TEMP.FILE,DISP=(NEW,PASS,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//*
//STEP2    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=INPUT.DATA,DISP=SHR
//SYSUT2   DD DSN=TEMP.FILE,DISP=(OLD,PASS)
//SYSIN    DD DUMMY
//*
//STEP3    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=TEMP.FILE,DISP=(OLD,DELETE)
//SORTOUT  DD DSN=FINAL.OUTPUT,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5),RLSE)
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//NOTIFY   JOB (ACCT),'WITH NOTIFY',CLASS=A,MSGCLASS=X,
//             NOTIFY=&SYSUID
//STEP1    EXEC PGM=IEFBR14
//SYSPRINT DD SYSOUT=*

//RESTART  JOB (ACCT),'RESTART JOB',CLASS=A,MSGCLASS=X,
//             RESTART=STEP2
//STEP1    EXEC PGM=PROG1
//SYSOUT   DD SYSOUT=*
//STEP2    EXEC PGM=PROG2
//SYSOUT   DD SYSOUT=*
//STEP3    EXEC PGM=PROG3
//SYSOUT   DD SYSOUT=*

//REGION   JOB (ACCT),'REGION JOB',CLASS=A,MSGCLASS=X,
//             REGION=4M
//STEP1    EXEC PGM=MYPROG,REGION=2M
//SYSOUT   DD SYSOUT=*

//TIMEJOB  JOB (ACCT),'TIME LIMIT',CLASS=A,MSGCLASS=X,
//             TIME=(5,30)
//STEP1    EXEC PGM=LONGPROG,TIME=2
//SYSOUT   DD SYSOUT=*

//RUNREXX  JOB (ACCT),'RUN REXX',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//SYSEXEC  DD DSN=MY.REXX.LIBRARY,DISP=SHR
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  %MYREXX ARG1 ARG2
/*

//PRINTVSM JOB (ACCT),'PRINT VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//INFILE   DD DSN=MY.VSAM.KSDS,DISP=SHR
//SYSIN    DD *
  PRINT INFILE(INFILE) -
        CHARACTER -
        COUNT(100)
/*

//RENAME   JOB (ACCT),'RENAME DS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  ALTER OLD.DATASET.NAME -
        NEWNAME(NEW.DATASET.NAME)
/*

//OUTPUTJB JOB (ACCT),'OUTPUT JOB',CLASS=A,MSGCLASS=X
//OUT1     OUTPUT DEST=LOCAL,COPIES=2,CLASS=A
//STEP1    EXEC PGM=MYPROG
//REPORT   DD SYSOUT=*,OUTPUT=*.OUT1

//ADDMEM   JOB (ACCT),'ADD MEMBER',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBUPDTE,PARM=NEW
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=MY.PDS.LIBRARY,DISP=OLD
//SYSUT2   DD DSN=MY.PDS.LIBRARY,DISP=OLD
//SYSIN    DD *
./ ADD NAME=NEWMEM
Line 1 of new member
Line 2 of new member
./ ENDUP
/*

//SIMPLE   JOB (ACCT),'SIMPLE JOB',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//SYSPRINT DD SYSOUT=*
